   227→    private fun applySynonym(token: CharVector, entry: RuleEntry) {
   228→        val synonyms: MutableList<CharSequence> = ArrayList()
   229→        if (option!!.useSynonym() && option!!.useForQuery()) {
   230→            if (synonymDictionary != null && synonymDictionary!!.containsKey(token)) {
   231→                val wordSynonym = synonymDictionary!!.get(token)
   232→                logger.trace("SYNONYM-FOUND:{}{}", "", wordSynonym)
   233→                if (wordSynonym != null) {
   234→                    synonyms.addAll(Arrays.asList(*wordSynonym))
   235→                }
   236→                if (typeAttribute.type() != UNIT) {
   237→                    val synonymsExt = synonymExtract(synonyms, entry)
   238→                    if (synonymsExt != null) {
   239→                        return applySynonymFinish(synonymsExt, entry)
   240→                    }
   241→                }
   242→            }
   243→        }
   244→        if (entry.synonym != null && option!!.useSynonym()) {
   245→            synonyms.addAll(Arrays.asList(*entry.synonym!!))
   246→        }
   247→        if (synonyms.size > 0) {
   248→            logger.trace("SET-SYNONYM:{}", synonyms)
   249→            synonymAttribute.setSynonyms(synonyms)
   250→        }
   251→    }
   252→
   253→    private fun applySynonymFinish(synonyms: List<CharSequence>, entry: RuleEntry) {
   254→        val result: MutableList<CharSequence> = ArrayList(synonyms)
   255→        if (entry.synonym != null && option!!.useSynonym()) {
   256→            result.addAll(Arrays.asList(*entry.synonym!!))
   257→        }
   258→        if (result.size > 0) {
   259→            logger.trace("SET-SYNONYM:{}", result)
   260→            synonymAttribute.setSynonyms(result)
   261→        }
   262→    }
   263→
   264→    fun synonymExtract(synonyms: List<CharSequence>, entry: RuleEntry): List<CharSequence>? {
   265→        val parsingRule = this.parsingRule!!.clone()
   266→        parsingRule.option = AnalyzerOption()
   267→        parsingRule.option!!.useSynonym(false)
   268→        parsingRule.option!!.useStopword(true)
   269→        val entryList: MutableList<RuleEntry> = ArrayList()
   270→
   271→        var result: MutableList<CharSequence>? = null
   272→        val dupSet: MutableSet<String> = HashSet()
   273→        for (synonymInx in synonyms.indices) {
   274→            val synonym = CharVector.valueOf(synonyms[synonymInx])
   275→            logger.trace("synonym:{}", synonym)
   276→
   277→            val synonymTokens: MutableList<CharVector> = ArrayList(1)
   278→            if (synonym is CharVector) {
   279→                if (synonym.hasWhitespaces()) {
   280→                    val terms = synonym.splitByWhitespace()
   281→                    for (term in terms) {
   282→                        if (term.length() > 0) {
   283→                            synonymTokens.add(term)
   284→                        }
   285→                    }
   286→                } else {
   287→                    synonymTokens.add(synonym)
   288→                }
   289→            }
   290→
   291→            val sb = StringBuilder()
   292→            for (synonymCV in synonymTokens) {
   293→                logger.trace("TRACING SYNONYM : {}", synonymCV)
   294→                extractor!!.setInput(synonymCV.array(), synonymCV.offset(), synonymCV.length())
   295→                var cvEntry = extractor!!.extract()
   296→                while (cvEntry != null) {
   297→                    val cv = synonymCV.clone()
   298→                    cv.offset(cvEntry.offset())
   299→                    cv.length(cvEntry.column())
   300→                    if (cv.length() < synonymCV.length()) {
   301→                        val trimmed = cv.trim()
   302→                        if (trimmed.length() > 0) {
   303→                            Entry.addEntry(entryList, trimmed, getTermType(trimmed), cvEntry.posTag(),
   304→                                entry.startOffset, entry.endOffset, spaceDictionary)
   305→                        }
   306→                    } else {
   307→                        Entry.addEntry(entryList, synonymCV, getTermType(synonymCV), cvEntry.posTag(),
   308→                            entry.startOffset, entry.endOffset, spaceDictionary)
   309→                        break
   310→                    }
   311→                    cvEntry = cvEntry.next()
   312→                }
   313→
   314→                if (entryList.size > 0) {
   315→                    logger.trace("SYNONYM-QUEUE:{}", entryList)
   316→                    parsingRule.processRule(entryList, false)
   317→                    val tokenCV = CharVector()
   318→                    while (entryList.size > 0) {
   319→                        entryList.removeAt(0).makeTerm(tokenCV)
   320→                        if (sb.isNotEmpty()) {
   321→                            sb.append(" ")
   322→                        }
   323→                        sb.append(tokenCV.toString())
   324→                    }
   325→                }
   326→            }
   327→
   328→            if (sb.isNotEmpty()) {
   329→                val idString = sb.toString()
   330→                if (!dupSet.contains(idString)) {
   331→                    if (result == null) {
   332→                        result = ArrayList()
   333→                    }
   334→                    result.add(idString)
   335→                    logger.trace("synonym:{}", idString)
   336→                    dupSet.add(idString)
   337→                }
   338→            }
   339→        }
   340→        return result
   341→    }
   342→
   343→    fun testEntry(entry: RuleEntry, parent: RuleEntry?) {
   344→        if ((parent == null || parent.type == MODEL_NAME) && entry.type == NUMBER && entry.length >= 5) {
   345→            entry.type = MODEL_NAME
   346→        } else if (entry.type == UNIT_ALPHA) {
   347→            entry.type = UNIT
   348→        } else if (entry.type == NUMBER_TRANS) {
   349→            entry.type = NUMBER
   350→            val entryStr = CharVector(entry.makeTerm(null).toString().replace(",", ""))
   351→            if (entryStr.length() != entry.length) {
   352→                if (option!!.useForQuery()) {
   353→                    if (entry.length != entryStr.length()) {
   354→                        extraTermAttribute.addExtraTerm(entryStr.toString(), NUMBER, null)
   355→                    }
   356→                } else if (parent != null) {
   357→                    var subEntryList = parent.subEntry
   358→                    if (subEntryList == null) {
   359→                        subEntryList = ArrayList()
   360→                        parent.subEntry = subEntryList
   361→                    }
   362→                    if (subEntryList[0] === entry) {
   363→                        subEntryList.add(1, RuleEntry(entryStr.array(), entryStr.offset(), entryStr.length(),
   364→                            entry.startOffset, entry.endOffset, entry.type))
   365→                    }
   366→                } else {
   367→                    var subEntryList = entry.subEntry
   368→                    if (subEntryList == null) {
   369→                        subEntryList = ArrayList()
   370→                        entry.subEntry = subEntryList
   371→                    }
   372→                    subEntryList.add(RuleEntry(entryStr.array(), entryStr.offset(), entryStr.length(),
   373→                        entry.startOffset, entry.endOffset, entry.type))
   374→                }
   375→            }
   376→        } else if (entry.type == null) {
   377→            entry.type = UNCATEGORIZED
   378→        }
   379→    }
   380→
   381→    private fun applyEntry(entry: RuleEntry): CharVector {
   382→        termAttribute.copyBuffer(entry.buf, entry.start, entry.length)
   383→        offsetAttribute.setOffset(entry.startOffset, entry.endOffset)
   384→        typeAttribute.setType(entry.type)
   385→        if (option!!.toUppercase()) {
   386→            toUppercase(termAttribute.buffer())
   387→        }
   388→        token = entry.makeTerm(null)
   389→        if (stopDictionary != null && stopDictionary!!.set().contains(token)) {
   390→            tokenAttribute.addState(TokenInfoAttribute.STATE_TERM_STOP)
   391→        } else {
   392→            tokenAttribute.rmState(TokenInfoAttribute.STATE_TERM_STOP)
   393→        }
   394→        return entry.makeTerm(null)
   395→    }
   396→
   397→    @Throws(IOException::class)
   398→    override fun reset() {
   399→        super.reset()
   400→        extraTermAttribute.init(this)
   401→        parsingRule = null
   402→        token = null
   403→        termList = ArrayList()
   404→        this.clearAttributes()
   405→    }
   406→
   407→    fun toUppercase(buffer: CharArray) {
   408→        for (inx in buffer.indices) {
   409→            buffer[inx] = Character.toUpperCase(buffer[inx])
   410→        }
   411→    }
   412→
